#include "bounce.hpp"
#include "playlist_ruler.hpp"
static void bounceTests(){Project p;p.tracks.resize(3);p.bpm=120;p.bars=4;p.loop=false;auto&t=p.tracks[0];t.name="Lead";t.volume=.37f;t.pan=-.2f;t.notes={{0,.5,60,.8f}};t.clips={{2,2},{6,2},{12,2}};t.output=2;t.automationEnabled=true;t.automationTarget=0;t.automation={{0,.4f},{16,.8f}};p.tracks[1].output=0;p.tracks[1].sends={{0,.5f,true,false}};auto before=projectJson(p,L"work/test-results/bounce.vamp");auto request=makeBounceRequest(p,{{0,0},{0,1}},0);auto snapshot=bounceSnapshot(p,request);check(request.first==2&&request.last==8&&snapshot.tracks[0].clips.size()==2,"bounce uses the selected clips and their complete range");check(snapshot.tracks[1].output==MasterChannel&&snapshot.tracks[1].sends[0].sidechain,"bounce isolates audible bus input and retains sidechain input");auto plan=compile(snapshot);plan->tapTrack=0;plan->latency=plan->tracks[0].outputLatency;ExportOptions options;options.rate=48000;options.bits=32;options.startBeat=request.first;options.endBeat=request.last;renderWav(*plan,L"work/test-results/bounce.wav",options);auto audio=readWav(L"work/test-results/bounce.wav");check(audio->left.size()==144000,"bounce renders exactly the selected duration");auto candidate=p;int lane=commitBounce(candidate,request,audio);check(lane==1&&candidate.tracks[0].clips.size()==1&&candidate.tracks[0].clips[0].beat==12,"bounce replaces only selected source clips");check(candidate.tracks[1].clips[0].beat==2&&candidate.tracks[1].pluginPaths.empty()&&candidate.tracks[1].volume==t.volume&&candidate.tracks[1].pan==t.pan,"bounce places a clean audio lane at the source position without processing inserts twice");check(candidate.tracks[1].output==3&&candidate.tracks[2].output==0&&candidate.tracks[1].automation.size()==t.automation.size()&&candidate.tracks[1].automation.front().value==t.automation.front().value,"bounce retains fader automation and remaps buses after lane insertion");check(projectJson(p,L"work/test-results/bounce.vamp")==before,"bounce preview preserves original sources");
    auto original=compile(p);auto bounced=compile(candidate);auto a=std::make_unique<Renderer>(),b=std::make_unique<Renderer>();a->locate(2*24000);b->locate(2*24000);std::array<float,1024>x{},y{};double error=0,energy=0;for(int n=0;n<250;n++){a->render(*original,x.data(),512,true);b->render(*bounced,y.data(),512,true);for(int i=0;i<1024;i++){error=std::max(error,double(std::abs(x[i]-y[i])));energy+=y[i]*y[i];}}check(error<3e-6&&energy>0,"bounce preserves sound, fader/pan automation, gaps and output routing");
    for(double width:{320.,568.,1000.,1800.}){double previous=0;for(double bars:{.25,.5,1.,2.,4.,8.,16.,32.,64.,128.,256.}){auto r=playlistRuler(13.125,bars*4,width,.25);check(r.labelStep>=previous,"ruler label spacing grows as the view zooms out");previous=r.labelStep;check(r.labelStep*width/(bars*4)>=72,"ruler labels retain minimum pixel spacing");for(size_t i=1;i<r.labels.size();i++)check(r.labels[i].beat>r.labels[i-1].beat,"ruler labels remain ordered");}}
    check(transportDigits(0)==std::array<std::wstring,3>{L"1",L"1",L"00"}&&transportDigits(4)==std::array<std::wstring,3>{L"2",L"1",L"00"}&&transportDigits(3.999)[2]==L"95","transport tick carry is consistent at beat/bar boundaries");
    std::ofstream(L"work/test-results/bounce.json")<<Json({{"passed",true},{"sound_difference",error},{"selected_source_preserved_until_commit",true},{"routing_and_automation",true},{"adaptive_ruler",true},{"transport_ticks",true}}).dump(2);
}
